def _dispatch_command(
    args: argparse.Namespace,
    *,
    base_url: str,
    request_fn: RequestFn,
    json_output: bool,
    out: TextIO,
    err: TextIO,
) -> int:
    handler = getattr(args, "handler", None)

    if handler == "help":
        build_parser().print_help(out)
        return 0

    if handler == "create":
        body: dict[str, Any] = {
            "project": args.project,
            "quest_type": args.type,
            "name": args.name,
        }
        if args.slug is not None:
            body["slug"] = args.slug
        endpoint = "/create_quest"
        status, data = _send_request(
            request_fn, "POST", base_url=base_url, endpoint=endpoint, body=body
        )
        if 200 <= status < 300:
            if json_output:
                _print_json(data, out)
            else:
                _format_create(data, base_url, out)
            return 0
        return _handle_http_result(
            status=status,
            endpoint=endpoint,
            data=data,
            json_output=json_output,
            out=out,
            err=err,
        )

    if handler == "run":
        body = {
            "project": args.project,
            "quest_type": args.type,
            "quest_number": args.number,
        }
        if args.max_steps is not None:
            body["max_steps"] = args.max_steps
        endpoint = "/run_quest"
        status, data = _send_request(
            request_fn, "POST", base_url=base_url, endpoint=endpoint, body=body
        )
        if 200 <= status < 300:
            if json_output:
                _print_json(data, out)
            else:
                _format_run(data, out)
            return 0
        return _handle_http_result(
            status=status,
            endpoint=endpoint,
            data=data,
            json_output=json_output,
            out=out,
            err=err,
        )

    if handler == "advance":
        body = {
            "project": args.project,
            "quest_type": args.type,
            "quest_number": args.number,
        }
        endpoint = "/advance_quest"
        status, data = _send_request(
            request_fn, "POST", base_url=base_url, endpoint=endpoint, body=body
        )
        if 200 <= status < 300:
            if json_output:
                _print_json(data, out)
            else:
                _format_advance(data, out)
            return 0
        return _handle_http_result(
            status=status,
            endpoint=endpoint,
            data=data,
            json_output=json_output,
            out=out,
            err=err,
        )

    if handler == "land":
        body = {
            "project": args.project,
            "quest_type": args.type,
            "quest_number": args.number,
            "target_branch": args.target_branch,
        }
        endpoint = "/land"
        status, data = _send_request(
            request_fn, "POST", base_url=base_url, endpoint=endpoint, body=body
        )
        if 200 <= status < 300:
            if json_output:
                _print_json(data, out)
            else:
                _format_land(data, out)
            return 0
        if not json_output:
            _format_land(data, err)
        return _handle_http_result(
            status=status,
            endpoint=endpoint,
            data=data,
            json_output=json_output,
            out=out,
            err=err,
        )

    if handler and handler.startswith("issues_"):
        _validate_scope(args.scope)
        _validate_slice_for_scope(args.scope, args.slice)

        project = args.project
        quest_type = args.type
        quest_number = args.number
        scope = args.scope
        slice_number = args.slice

        if handler == "issues_list":
            _validate_list_status(args.status)
            endpoint = "/api/issues"
            query = _issue_query(
                project,
                quest_type,
                quest_number,
                scope,
                slice_number,
                {"status": args.status},
            )
            status, data = _send_request(
                request_fn,
                "GET",
                base_url=base_url,
                endpoint=endpoint,
                query=query,
                body=None,
            )
            if 200 <= status < 300:
                if json_output:
                    _print_json(data, out)
                else:
                    _format_issue_list(data, out)
                return 0
            return _handle_http_result(
                status=status,
                endpoint=endpoint,
                data=data,
                json_output=json_output,
                out=out,
                err=err,
            )

        if handler == "issues_read":
            endpoint = f"/api/issues/{args.issue_id}"
            query = _issue_query(project, quest_type, quest_number, scope, slice_number)
            status, data = _send_request(
                request_fn,
                "GET",
                base_url=base_url,
                endpoint=endpoint,
                query=query,
                body=None,
            )
            if 200 <= status < 300:
                if json_output:
                    _print_json(data, out)
                else:
                    _format_issue(data, out)
                    responses = data.get("responses")
                    if isinstance(responses, list) and responses:
                        out.write("\nresponses:\n")
                        _format_responses_list({"responses": responses}, out)
                return 0
            return _handle_http_result(
                status=status,
                endpoint=endpoint,
                data=data,
                json_output=json_output,
                out=out,
                err=err,
            )

        if handler == "issues_create":
            body_text = _read_text_source(args.body, args.body_file, "body")
            _validate_issue_status(args.status)
            endpoint = "/api/issues"
            body = _issue_body(
                project,
                quest_type,
                quest_number,
                scope,
                slice_number,
                {"title": args.title, "body": body_text, "status": args.status},
            )
            status, data = _send_request(
                request_fn, "POST", base_url=base_url, endpoint=endpoint, body=body
            )
            if 200 <= status < 300:
                if json_output:
                    _print_json(data, out)
                else:
                    _format_issue(data, out)
                return 0
            return _handle_http_result(
                status=status,
                endpoint=endpoint,
                data=data,
                json_output=json_output,
                out=out,
                err=err,
            )

        if handler == "issues_edit":
            if args.body is not None and args.body_file is not None:
                raise CliValidationError("--body and --body-file are mutually exclusive")
            if args.status is None and args.title is None and args.body is None and args.body_file is None:
                raise CliValidationError(
                    "At least one of --status, --title, --body, or --body-file is required"
                )
            if args.status is not None:
                _validate_issue_status(args.status)
            endpoint = f"/api/issues/{args.issue_id}"
            extra: dict[str, Any] = {}
            if args.status is not None:
                extra["status"] = args.status
            if args.title is not None:
                extra["title"] = args.title
            if args.body is not None or args.body_file is not None:
                extra["body"] = _read_text_source(args.body, args.body_file, "body")
            body = _issue_body(project, quest_type, quest_number, scope, slice_number, extra)
            status, data = _send_request(
                request_fn, "PATCH", base_url=base_url, endpoint=endpoint, body=body
            )
            if 200 <= status < 300:
                if json_output:
                    _print_json(data, out)
                else:
                    _format_issue(data, out)
                return 0
            return _handle_http_result(
                status=status,
                endpoint=endpoint,
                data=data,
                json_output=json_output,
                out=out,
                err=err,
            )

        if handler == "issues_respond":
            _validate_outcome(args.outcome)
            explanation = _read_text_source(args.explanation, args.explanation_file, "explanation")
            endpoint = f"/api/issues/{args.issue_id}/responses"
            body = _issue_body(
                project,
                quest_type,
                quest_number,
                scope,
                slice_number,
                {"outcome": args.outcome, "explanation": explanation},
            )
            status, data = _send_request(
                request_fn, "POST", base_url=base_url, endpoint=endpoint, body=body
            )
            if 200 <= status < 300:
                if json_output:
                    _print_json(data, out)
                else:
                    _format_respond(data, out)
                return 0
            return _handle_http_result(
                status=status,
                endpoint=endpoint,
                data=data,
                json_output=json_output,
                out=out,
                err=err,
            )

        if handler == "issues_responses":
            endpoint = f"/api/issues/{args.issue_id}/responses"
            query = _issue_query(project, quest_type, quest_number, scope, slice_number)
            status, data = _send_request(
                request_fn,
                "GET",
                base_url=base_url,
                endpoint=endpoint,
                query=query,
                body=None,
            )
            if 200 <= status < 300:
                if json_output:
                    _print_json(data, out)
                else:
                    _format_responses_list(data, out)
                return 0
            return _handle_http_result(
                status=status,
                endpoint=endpoint,
                data=data,
                json_output=json_output,
                out=out,
                err=err,
            )

    build_parser().print_help(err)
    return 2


def main(
    argv: list[str] | None = None,
    *,
    request_fn: RequestFn | None = None,
    stdout: TextIO | None = None,
    stderr: TextIO | None = None,
    env: dict[str, str] | None = None,
    start_path: Path | None = None,
) -> int:
    parser = build_parser()
    args = parser.parse_args(argv)
    out = sys.stdout if stdout is None else stdout
    err = sys.stderr if stderr is None else stderr
    json_output = bool(args.json)

    base_url, warning = resolve_base_url(
        cli_base_url=args.base_url,
        env=env,
        start_path=start_path if start_path is not None else _script_start_path(argv),
    )
    if warning and not json_output:
        err.write(warning + "\n")

    if args.command is None:
        parser.print_help(out)
        return 0

    try:
        transport = default_request if request_fn is None else request_fn
        return _dispatch_command(
            args,
            base_url=base_url,
            request_fn=transport,
            json_output=json_output,
            out=out,

        "run_quest scheduled run_id=%s status=%s",
        result.get("run_id"),
        result.get("status"),
    )
    return jsonify(result), 202

